import{_ as e,c as t,o as a,a2 as s}from"./chunks/framework.DdOM6S6U.js";const g=JSON.parse('{"title":"AuthenticateMiddleware","description":"","frontmatter":{"sidebarPos":2,"sidebarTitle":"AuthenticateMiddleware"},"headers":[],"relativePath":"system-reference/backend/http/middleware/authenticate.md","filePath":"system-reference/backend/http/middleware/authenticate.md","lastUpdated":1778363927000}'),i={name:"system-reference/backend/http/middleware/authenticate.md"},d=s(`<h1 id="authenticatemiddleware" tabindex="-1">AuthenticateMiddleware <a class="header-anchor" href="#authenticatemiddleware" aria-label="Permalink to &quot;AuthenticateMiddleware&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Middleware/AuthenticateMiddleware.php</code><br><strong>Alias</strong>: <code>modularous.auth</code><br><strong>Extends</strong>: <code>Illuminate\\Auth\\Middleware\\Authenticate</code></p><p>Extends Laravel&#39;s built-in <code>Authenticate</code> middleware with two Modularous-specific behaviours: intended-URL preservation before the redirect and JSON 401 handling for Inertia/AJAX requests.</p><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><h3 id="standard-html-requests" tabindex="-1">Standard HTML requests <a class="header-anchor" href="#standard-html-requests" aria-label="Permalink to &quot;Standard HTML requests&quot;">​</a></h3><p>When an unauthenticated browser request hits a protected route:</p><ol><li>The current URL is saved to <code>session(&#39;url.intended&#39;)</code> via <code>session()-&gt;put(&#39;url.intended&#39;, url()-&gt;previous())</code>.</li><li>The user is redirected to the admin login route (<code>admin.login.form</code>).</li></ol><p><strong>Excluded routes</strong> — the intended URL is NOT stored when the current route is any of:</p><table><thead><tr><th>Route name (prefixed)</th></tr></thead><tbody><tr><td><code>login.form</code>, <code>login</code>, <code>logout</code></td></tr><tr><td><code>register.form</code>, <code>register</code>, <code>register.success</code></td></tr><tr><td><code>password.reset.*</code></td></tr><tr><td><code>impersonate</code>, <code>impersonate.stop</code></td></tr></tbody></table><p>This prevents the login page itself (or other auth pages) from being set as the post-login destination.</p><h3 id="json-inertia-requests" tabindex="-1">JSON / Inertia requests <a class="header-anchor" href="#json-inertia-requests" aria-label="Permalink to &quot;JSON / Inertia requests&quot;">​</a></h3><p>When the request expects JSON (<code>Accept: application/json</code>):</p><ul><li>The <code>Referer</code> header is stored in <code>session(&#39;url.intended&#39;)</code>.</li><li>Returns a <code>401 JSON</code> response:<div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Unauthenticated.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;experimental&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div></li></ul><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>Applied via the <code>web.auth</code> and <code>api.auth</code> middleware groups:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Route</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">middlewareGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;web.auth&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;web&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;modularous.auth:modularous&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span></code></pre></div><p>The guard name is injected from <code>Modularous::getAuthGuardName()</code> (default: <code>&#39;modularous&#39;</code>).</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>After a successful login, the <code>RedirectService</code> or Laravel&#39;s <code>url()-&gt;intended()</code> uses the stored URL to redirect the user back.</li><li>The <code>mode: experimental</code> field in the JSON 401 is a placeholder for future Inertia partial-reload handling.</li></ul>`,19),r=[d];function o(n,l,h,c,p,u){return a(),t("div",null,r)}const m=e(i,[["render",o]]);export{g as __pageData,m as default};
